#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_N 10
#define MAX_M 10
#define MAX_CELLS (MAX_N * MAX_M)

int N, M;
char grid[MAX_N][MAX_M + 1];
int house_count;
int start_r, start_c;
int dp[1 << (MAX_CELLS)][MAX_N][MAX_M][4]; // dp[mask][r][c][dir]

int dr[4] = {-1, 0, 1, 0};
int dc[4] = {0, 1, 0, -1};

int solve() {
    // Find church and count houses
    house_count = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            if (grid[i][j] == 'C') {
                start_r = i;
                start_c = j;
            } else if (grid[i][j] == 'H') {
                house_count++;
            }
        }
    }

    if (house_count == 0) {
        // No houses: just one route: start and immediately return? 
        // According to problem: must deliver to each house exactly once before returning.
        // If no houses, route is: from church to church without delivering. That's valid.
        return 1;
    }

    int total_cells = N * M;
    int max_mask = 1 << house_count;

    // Map each house to an index
    int house_index[MAX_N][MAX_M];
    memset(house_index, -1, sizeof(house_index));
    int idx = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            if (grid[i][j] == 'H') {
                house_index[i][j] = idx++;
            }
        }
    }

    // Initialize dp to -1 (uncomputed)
    memset(dp, -1, sizeof(dp));

    // For each starting direction from church
    int result = 0;
    for (int dir = 0; dir < 4; dir++) {
        int nr = start_r + dr[dir];
        int nc = start_c + dc[dir];
        if (nr < 0 || nr >= N || nc < 0 || nc >= M) continue;
        // Must land on a house (since cannot land on empty or church except at end)
        if (grid[nr][nc] == 'H') {
            int mask = 1 << house_index[nr][nc];
            dp[mask][nr][nc][dir] = 1;
        }
    }

    // Iterate over masks
    for (int mask = 1; mask < max_mask; mask++) {
        for (int r = 0; r < N; r++) {
            for (int c = 0; c < M; c++) {
                for (int dir = 0; dir < 4; dir++) {
                    int cur = dp[mask][r][c][dir];
                    if (cur == -1) continue;
                    // Try to continue in same direction
                    int nr = r + dr[dir];
                    int nc = c + dc[dir];
                    if (nr >= 0 && nr < N && nc >= 0 && nc < M) {
                        if (grid[nr][nc] == 'H') {
                            int hidx = house_index[nr][nc];
                            if (!(mask & (1 << hidx))) {
                                int new_mask = mask | (1 << hidx);
                                dp[new_mask][nr][nc][dir] += cur;
                            }
                        } else if (grid[nr][nc] == 'C' && mask == max_mask - 1) {
                            // If we reach church after delivering all houses, count route
                            result += cur;
                        }
                        // Empty lots: can pass over, so continue
                        else if (grid[nr][nc] == '.') {
                            dp[mask][nr][nc][dir] += cur;
                        }
                    }
                }
            }
        }
    }

    return result;
}

int main() {
    scanf("%d %d", &N, &M);
    for (int i = 0; i < N; i++) {
        scanf("%s", grid[i]);
    }
    int ans = solve();
    printf("%d\n", ans);
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 10
#define MAXH 20

int R, C;
char grid[MAXN][MAXN+1];
int church_r, church_c;
int house_r[MAXH], house_c[MAXH];
int num_houses;
// cell_type: 0=empty, 1=church, 2=house (index in house array)
int cell_house[MAXN][MAXN]; // -1 if not a house, else house index

int dr[] = {-1, 1, 0, 0};
int dc[] = {0, 0, -1, 1};

long long ans = 0;

void dfs(int r, int c, int visited, int count) {
    if (count == num_houses) {
        // Try to return to church
        for (int d = 0; d < 4; d++) {
            int nr = r + dr[d], nc = c + dc[d];
            while (nr >= 0 && nr < R && nc >= 0 && nc < C) {
                // Check intermediate: current step cell
                if (grid[nr][nc] == 'H') {
                    int hi = cell_house[nr][nc];
                    if (visited & (1 << hi)) break; // blocked
                    // can pass over unvisited house without landing? But we're looking for church
                    // we pass over it, continue
                }
                if (grid[nr][nc] == 'C') {
                    ans++;
                    break;
                }
                nr += dr[d]; nc += dc[d];
            }
        }
        return;
    }

    for (int d = 0; d < 4; d++) {
        int nr = r + dr[d], nc = c + dc[d];
        while (nr >= 0 && nr < R && nc >= 0 && nc < C) {
            if (grid[nr][nc] == 'H') {
                int hi = cell_house[nr][nc];
                if (visited & (1 << hi)) break; // visited house blocks path
                // Land here
                dfs(nr, nc, visited | (1 << hi), count + 1);
                // Or pass over (continue flying)
            }
            // empty lot or church: can pass over but not land (church needs all delivered)
            nr += dr[d]; nc += dc[d];
        }
    }
}

int main() {
    scanf("%d %d", &R, &C);
    memset(cell_house, -1, sizeof(cell_house));
    num_houses = 0;
    for (int i = 0; i < R; i++) {
        scanf("%s", grid[i]);
        for (int j = 0; j < C; j++) {
            if (grid[i][j] == 'C') { church_r = i; church_c = j; }
            else if (grid[i][j] == 'H') {
                cell_house[i][j] = num_houses;
                house_r[num_houses] = i; house_c[num_houses] = j;
                num_houses++;
            }
        }
    }
    dfs(church_r, church_c, 0, 0);
    printf("%lld\n", ans);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXH 20
#define MAXW 20
#define MAXN 20
#define MAXM (1<<20)

int H, W;
char S[MAXH][MAXW + 1];

int hx[MAXN], hy[MAXN], houseCnt;
int churchX, churchY;

/* startMask[d][i]:
   bitmask of houses that are strictly between the church and house i
   when moving from church to house i in direction d.
   d: 0=up,1=down,2=left,3=right
   validStart[d][i]: whether house i is reachable from church in direction d
*/
unsigned int startMask[4][MAXN];
int validStart[4][MAXN];

/* moveMask[d][i][j]:
   bitmask of houses strictly between house i and house j
   when moving from house i to house j in direction d.
   validMove[d][i][j]: whether j is reachable from i in direction d
*/
unsigned int moveMask[4][MAXN][MAXN];
int validMove[4][MAXN][MAXN];

/* endMask[d][i]:
   bitmask of houses strictly between house i and church
   when moving from house i to church in direction d.
   validEnd[d][i]: whether church is reachable from i in direction d
*/
unsigned int endMask[4][MAXN];
int validEnd[4][MAXN];

long long *dp[4];

int dir_between(int x1, int y1, int x2, int y2) {
    if (x2 < x1 && y1 == y2) return 0; /* up */
    if (x2 > x1 && y1 == y2) return 1; /* down */
    if (x1 == x2 && y2 < y1) return 2; /* left */
    if (x1 == x2 && y2 > y1) return 3; /* right */
    return -1;
}

int main(void) {
    if (scanf("%d %d", &H, &W) != 2) return 0;
    for (int i = 0; i < H; i++) scanf("%s", S[i]);

    houseCnt = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (S[i][j] == 'H') {
                hx[houseCnt] = i;
                hy[houseCnt] = j;
                houseCnt++;
            } else if (S[i][j] == 'C') {
                churchX = i;
                churchY = j;
            }
        }
    }

    unsigned int fullMask = (houseCnt == 32 ? 0xFFFFFFFFu : ((1u << houseCnt) - 1u));

    memset(validStart, 0, sizeof(validStart));
    memset(validMove, 0, sizeof(validMove));
    memset(validEnd, 0, sizeof(validEnd));
    memset(startMask, 0, sizeof(startMask));
    memset(moveMask, 0, sizeof(moveMask));
    memset(endMask, 0, sizeof(endMask));

    /* Precompute church -> house */
    for (int i = 0; i < houseCnt; i++) {
        int d = dir_between(churchX, churchY, hx[i], hy[i]);
        if (d == -1) continue;
        validStart[d][i] = 1;
        unsigned int mask = 0;
        for (int k = 0; k < houseCnt; k++) {
            if (k == i) continue;
            if (d == 0 && hy[k] == churchY && hx[i] < hx[k] && hx[k] < churchX) mask |= (1u << k);
            if (d == 1 && hy[k] == churchY && churchX < hx[k] && hx[k] < hx[i]) mask |= (1u << k);
            if (d == 2 && hx[k] == churchX && hy[i] < hy[k] && hy[k] < churchY) mask |= (1u << k);
            if (d == 3 && hx[k] == churchX && churchY < hy[k] && hy[k] < hy[i]) mask |= (1u << k);
        }
        startMask[d][i] = mask;
    }

    /* Precompute house -> house */
    for (int i = 0; i < houseCnt; i++) {
        for (int j = 0; j < houseCnt; j++) {
            if (i == j) continue;
            int d = dir_between(hx[i], hy[i], hx[j], hy[j]);
            if (d == -1) continue;
            validMove[d][i][j] = 1;
            unsigned int mask = 0;
            for (int k = 0; k < houseCnt; k++) {
                if (k == i || k == j) continue;
                if (d == 0 && hy[k] == hy[i] && hx[j] < hx[k] && hx[k] < hx[i]) mask |= (1u << k);
                if (d == 1 && hy[k] == hy[i] && hx[i] < hx[k] && hx[k] < hx[j]) mask |= (1u << k);
                if (d == 2 && hx[k] == hx[i] && hy[j] < hy[k] && hy[k] < hy[i]) mask |= (1u << k);
                if (d == 3 && hx[k] == hx[i] && hy[i] < hy[k] && hy[k] < hy[j]) mask |= (1u << k);
            }
            moveMask[d][i][j] = mask;
        }
    }

    /* Precompute house -> church */
    for (int i = 0; i < houseCnt; i++) {
        int d = dir_between(hx[i], hy[i], churchX, churchY);
        if (d == -1) continue;
        validEnd[d][i] = 1;
        unsigned int mask = 0;
        for (int k = 0; k < houseCnt; k++) {
            if (k == i) continue;
            if (d == 0 && hy[k] == hy[i] && churchX < hx[k] && hx[k] < hx[i]) mask |= (1u << k);
            if (d == 1 && hy[k] == hy[i] && hx[i] < hx[k] && hx[k] < churchX) mask |= (1u << k);
            if (d == 2 && hx[k] == hx[i] && churchY < hy[k] && hy[k] < hy[i]) mask |= (1u << k);
            if (d == 3 && hx[k] == hx[i] && hy[i] < hy[k] && hy[k] < churchY) mask |= (1u << k);
        }
        endMask[d][i] = mask;
    }

    int states = 1 << houseCnt;
    for (int d = 0; d < 4; d++) {
        dp[d] = (long long*)calloc((size_t)states * houseCnt, sizeof(long long));
    }

    /* Initial moves from church */
    for (int d = 0; d < 4; d++) {
        for (int i = 0; i < houseCnt; i++) {
            if (!validStart[d][i]) continue;
            if (startMask[d][i] == 0) {
                dp[d][(1 << i) * houseCnt + i] = 1;
            }
        }
    }

    /* DP */
    for (int mask = 1; mask < states; mask++) {
        for (int d = 0; d < 4; d++) {
            for (int i = 0; i < houseCnt; i++) {
                long long cur = dp[d][mask * houseCnt + i];
                if (!cur) continue;

                for (int nd = 0; nd < 4; nd++) {
                    if (nd == d) continue;
                    for (int j = 0; j < houseCnt; j++) {
                        if (mask & (1 << j)) continue;
                        if (!validMove[nd][i][j]) continue;
                        if ((moveMask[nd][i][j] & mask) == 0) {
                            dp[nd][(mask | (1 << j)) * houseCnt + j] += cur;
                        }
                    }
                }
            }
        }
    }

    long long ans = 0;
    for (int d = 0; d < 4; d++) {
        for (int i = 0; i < houseCnt; i++) {
            long long cur = dp[d][fullMask * houseCnt + i];
            if (!cur) continue;
            for (int nd = 0; nd < 4; nd++) {
                if (nd == d) continue;
                if (!validEnd[nd][i]) continue;
                if ((endMask[nd][i] & fullMask) == endMask[nd][i]) {
                    ans += cur;
                }
            }
        }
    }

    printf("%lld\n", ans);

    for (int d = 0; d < 4; d++) free(dp[d]);
    return 0;
}

