public class Main {
    static int H, W;
    static char[][] grid;
    static int totalHouses;
    static int churchR, churchC;
    static List<int[]> houseList;
    static Map<Long, Integer> memo;
    static int[] dr = {-1, 1, 0, 0};
    static int[] dc = {0, 0, -1, 1};

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        H = Integer.parseInt(parts[0]);
        W = Integer.parseInt(parts[1]);
        grid = new char[H][W];
        houseList = new ArrayList<>();

        for (int i = 0; i < H; i++) {
            String line = br.readLine();
            for (int j = 0; j < W; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'C') {
                    churchR = i;
                    churchC = j;
                } else if (grid[i][j] == 'H') {
                    houseList.add(new int[]{i, j});
                }
            }
        }
        totalHouses = houseList.size();

        if (totalHouses == 0) {
            System.out.println(0);
            return;
        }

        // Precompute distances between all houses and church
        int N = totalHouses;
        int[][] dist = new int[N + 1][N + 1]; // index N = church

        for (int i = 0; i < N; i++) {
            int[] a = houseList.get(i);
            for (int j = i + 1; j < N; j++) {
                int[] b = houseList.get(j);
                int d = bfsDist(a[0], a[1], b[0], b[1]);
                dist[i][j] = dist[j][i] = d;
            }
            int d = bfsDist(a[0], a[1], churchR, churchC);
            dist[i][N] = dist[N][i] = d;
        }

        memo = new HashMap<>();
        long fullMask = (1L << N) - 1;
        long result = 0;

        // Try all possible first houses
        for (int first = 0; first < N; first++) {
            if (dist[N][first] == -1) continue;
            result += dfs(first, 1L << first, dist, N);
        }

        System.out.println(result);
    }

    static long dfs(int last, long mask, int[][] dist, int N) {
        if (mask == (1L << N) - 1) {
            // All houses visited, check if can return to church
            return dist[last][N] != -1 ? 1 : 0;
        }

        long key = ((long) last << 32) | mask;
        if (memo.containsKey(key)) return memo.get(key);

        long total = 0;
        for (int next = 0; next < N; next++) {
            if ((mask & (1L << next)) != 0) continue;
            if (dist[last][next] == -1) continue;
            total += dfs(next, mask | (1L << next), dist, N);
        }

        memo.put(key, total);
        return total;
    }

    static int bfsDist(int sr, int sc, int tr, int tc) {
        if (sr == tr && sc == tc) return 0;
        boolean[][] visited = new boolean[H][W];
        Queue<int[]> queue = new LinkedList<>();
        queue.add(new int[]{sr, sc});
        visited[sr][sc] = true;
        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            steps++;
            for (int s = 0; s < size; s++) {
                int[] cur = queue.poll();
                int r = cur[0], c = cur[1];

                // Try all 4 directions, but must go straight
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    // Move in straight line
                    while (nr >= 0 && nr < H && nc >= 0 && nc < W && 
                           grid[nr][nc] != 'E' && !visited[nr][nc]) {
                        if (nr == tr && nc == tc) return steps;
                        visited[nr][nc] = true;
                        // If we hit a house (not target) we can land on it, but must stop there
                        if (grid[nr][nc] == 'H' || grid[nr][nc] == 'C') {
                            // Can land here but cannot go further in same line
                            break;
                        }
                        nr += dr[d];
                        nc += dc[d];
                    }
                }
            }
        }
        return -1;
    }
}

