import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 100000L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int H = fs.nextInt();
        int W = fs.nextInt();

        char[][] grid = new char[H][W];
        ArrayList<int[]> houses = new ArrayList<>();
        int sr = -1, sc = -1;

        for (int i = 0; i < H; i++) {
            String s = fs.next();
            for (int j = 0; j < W; j++) {
                grid[i][j] = s.charAt(j);
                if (grid[i][j] == 'H') {
                    houses.add(new int[]{i, j});
                } else if (grid[i][j] == 'C') {
                    sr = i;
                    sc = j;
                }
            }
        }

        int n = houses.size();
        int totalNodes = n + 1; // 0 = church, 1..n = houses

        int[] rr = new int[totalNodes];
        int[] cc = new int[totalNodes];
        rr[0] = sr;
        cc[0] = sc;
        for (int i = 0; i < n; i++) {
            rr[i + 1] = houses.get(i)[0];
            cc[i + 1] = houses.get(i)[1];
        }

        // between[u][v] = bitmask of houses strictly between u and v on same row/col, else -1
        int[][] between = new int[totalNodes][totalNodes];
        for (int i = 0; i < totalNodes; i++) Arrays.fill(between[i], -1);

        for (int i = 0; i < totalNodes; i++) {
            for (int j = 0; j < totalNodes; j++) {
                if (i == j) continue;
                if (rr[i] == rr[j]) {
                    int row = rr[i];
                    int l = Math.min(cc[i], cc[j]);
                    int r = Math.max(cc[i], cc[j]);
                    int mask = 0;
                    for (int k = 1; k <= n; k++) {
                        if (rr[k] == row && l < cc[k] && cc[k] < r) {
                            mask |= 1 << (k - 1);
                        }
                    }
                    between[i][j] = mask;
                } else if (cc[i] == cc[j]) {
                    int col = cc[i];
                    int l = Math.min(rr[i], rr[j]);
                    int r = Math.max(rr[i], rr[j]);
                    int mask = 0;
                    for (int k = 1; k <= n; k++) {
                        if (cc[k] == col && l < rr[k] && rr[k] < r) {
                            mask |= 1 << (k - 1);
                        }
                    }
                    between[i][j] = mask;
                }
            }
        }

        // DP[mask][u]: ways to start at church, visit exactly houses in mask, and be at node u (1..n)
        int maxMask = 1 << n;
        int[][] dp = new int[maxMask][totalNodes];

        // first move from church to a house
        for (int v = 1; v <= n; v++) {
            int b = between[0][v];
            if (b != -1 && b == 0) {
                dp[1 << (v - 1)][v] = 1;
            }
        }

        for (int mask = 0; mask < maxMask; mask++) {
            for (int u = 1; u <= n; u++) {
                int cur = dp[mask][u];
                if (cur == 0) continue;
                if ((mask & (1 << (u - 1))) == 0) continue;

                for (int v = 1; v <= n; v++) {
                    if ((mask & (1 << (v - 1))) != 0) continue;
                    int b = between[u][v];
                    if (b == -1) continue;
                    // Can pass only over unvisited houses, so no visited house may be strictly between
                    if ((b & mask) != 0) continue;
                    int nmask = mask | (1 << (v - 1));
                    int nv = dp[nmask][v] + cur;
                    if (nv >= MOD) nv -= MOD;
                    dp[nmask][v] = nv;
                }
            }
        }

        int full = maxMask - 1;
        int ans = 0;
        for (int u = 1; u <= n; u++) {
            int cur = dp[full][u];
            if (cur == 0) continue;
            int b = between[u][0];
            if (b == -1) continue;
            // returning to church after all houses visited: no issue since all houses visited,
            // but cannot pass over already visited houses, so there must be none strictly between.
            if (b != 0) continue;
            ans += cur;
            if (ans >= MOD) ans -= MOD;
        }

        System.out.println(ans % MOD);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

