int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> H >> W;
    grid.resize(H);
    for (int i = 0; i < H; i++) {
        cin >> grid[i];
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 'C') church = {i, j};
            else if (grid[i][j] == 'H') totalHouses++;
        }
    }
    // Nodes: 0 = church, 1..totalHouses = houses
    vector<pair<int,int>> nodes;
    nodes.push_back(church);
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == 'H') nodes.push_back({i, j});
        }
    }
    int N = totalHouses + 1; // including church
    // Precompute distances between all pairs of nodes using BFS (with constraints)
    // The movement constraints: can only fly straight in one direction, cannot change direction mid-air.
    // So from a node, we can go in 4 directions until hitting an obstacle (house that already got present? Actually we can fly over houses not yet visited.
    // But we need to model that after visiting some houses, those become blocked. That's tricky.
    // However, since houses <= 10, we can do DP over subsets and precompute reachability with blocked cells.
    // Actually we can treat that when we have visited a set of houses, those houses are blocked.
    // So from a node, we can move in 4 directions, but cannot step onto a visited house cell (except the destination if it's unvisited house or church).
    // Church is never blocked.
    // Empty lots are always passable.
    // So we need for each subset of houses, the distance between two nodes avoiding visited houses.
    // Precompute for each mask (subset of houses) the distance between any two nodes.
    // But N <= 11, masks up to 2^10 = 1024, nodes <= 11, so 1024*11*11 ~ 124k BFS, each BFS O(H*W) = 100, total ~ 12 million, fine.

    vector<vector<vector<int>>> dist(1<<totalHouses, vector<vector<int>>(N, vector<int>(N, -1)));
    int dirs[4][2] = {{1,0},{-1,0},{0,1},{0,-1}};
    for (int mask = 0; mask < (1<<totalHouses); mask++) {
        // BFS from each node
        for (int s = 0; s < N; s++) {
            auto [sr, sc] = nodes[s];
            vector<vector<int>> d(H, vector<int>(W, -1));
            queue<pair<int,int>> q;
            q.push({sr, sc});
            d[sr][sc] = 0;
            while (!q.empty()) {
                auto [r, c] = q.front(); q.pop();
                for (auto &dd : dirs) {
                    int nr = r + dd[0];
                    int nc = c + dd[1];
                    if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                    if (d[nr][nc] != -1) continue;
                    char cell = grid[nr][nc];
                    if (cell == 'E') {
                        d[nr][nc] = d[r][c] + 1;
                        q.push({nr, nc});
                    } else if (cell == 'H') {
                        // find house index
                        int hidx = -1;
                        for (int i = 1; i < N; i++) {
                            if (nodes[i] == make_pair(nr, nc)) { hidx = i-1; break; }
                        }
                        // if house is not visited in mask, can pass through but not land? Actually we can pass over houses that have not yet received presents.
                        // So we can step onto it.
                        // If it is visited (blocked), cannot step onto.
                        if (!(mask & (1<<hidx))) {
                            d[nr][nc] = d[r][c] + 1;
                            q.push({nr, nc});
                        }
                    } else if (cell == 'C') {
                        d[nr][nc] = d[r][c] + 1;
                        q.push({nr, nc});
                    }
                }
            }
            // fill distances to all nodes
            for (int t = 0; t < N; t++) {
                auto [tr, tc] = nodes[t];
                dist[mask][s][t] = d[tr][tc];
            }
        }
    }

    // DP over subsets
    // dp[mask][last] = number of ways to have visited set mask (bits for houses) and currently at node last (0 = church, 1..totalHouses = house index)
    vector<vector<long long>> dp(1<<totalHouses, vector<long long>(N, 0));
    // start at church, mask = 0, last = 0
    dp[0][0] = 1;
    for (int mask = 0; mask < (1<<totalHouses); mask++) {
        for (int last = 0; last < N; last++) {
            if (dp[mask][last] == 0) continue;
            // try to go to an unvisited house
            for (int nxt = 1; nxt < N; nxt++) {
                int hidx = nxt-1;
                if (mask & (1<<hidx)) continue;
                int d = dist[mask][last][nxt];
                if (d == -1) continue;
                int newMask = mask | (1<<hidx);
                dp[newMask][nxt] += dp[mask][last];
            }
        }
    }
    // After all houses visited, must return to church
    long long ans = 0;
    int fullMask = (1<<totalHouses) - 1;
    for (int last = 1; last < N; last++) {
        int d = dist[fullMask][last][0];
        if (d == -1) continue;
        ans += dp[fullMask][last];
    }
    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int R, C;
vector<string> grid;
int churchR, churchC;
vector<pair<int,int>> houses;
int N; // number of houses
map<pair<int,int>, int> houseIdx;
long long ans = 0;

int dx[] = {0,0,1,-1};
int dy[] = {1,-1,0,0};

void dfs(int r, int c, int visited, int count) {
    if (count == N) {
        // try to return to church
        for (int d = 0; d < 4; d++) {
            int nr = r + dx[d], nc = c + dy[d];
            bool blocked = false;
            while (nr >= 0 && nr < R && nc >= 0 && nc < C) {
                if (nr == churchR && nc == churchC) { ans++; break; }
                if (grid[nr][nc] == 'H') { blocked = true; break; }
                nr += dx[d]; nc += dy[d];
            }
        }
        return;
    }
    for (int d = 0; d < 4; d++) {
        int nr = r + dx[d], nc = c + dy[d];
        while (nr >= 0 && nr < R && nc >= 0 && nc < C) {
            char cell = grid[nr][nc];
            if (cell == 'H') {
                auto it = houseIdx.find({nr, nc});
                int idx = it->second;
                if (!(visited & (1 << idx))) {
                    dfs(nr, nc, visited | (1 << idx), count + 1);
                }
                break; // can't pass visited house; if unvisited, we either land or... we must stop here
            }
            // empty or church: continue
            nr += dx[d]; nc += dy[d];
        }
    }
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int H, W;
vector<string> S;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> H >> W;
    S.resize(H);
    for (int i = 0; i < H; i++) cin >> S[i];

    vector<pair<int,int>> houses;
    int sy = -1, sx = -1;

    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            if (S[y][x] == 'H') houses.push_back({y, x});
            else if (S[y][x] == 'C') sy = y, sx = x;
        }
    }

    int N = (int)houses.size();

    // Important observation:
    // Since Santa flies in a straight cardinal direction and cannot pass over
    // already visited houses, the sequence of visited houses/church must form
    // a Hamiltonian cycle in the graph where vertices are the church + houses,
    // and two vertices are adjacent iff they are on the same row/column and
    // there is no house strictly between them.
    //
    // Empty lots and the church do not block flight; only already visited houses do.
    // Thus, from any current vertex, the next landing point in a chosen direction
    // must be the first house/church encountered in that direction.
    //
    // Build this graph, then count Hamiltonian cycles starting/ending at the church.

    vector<pair<int,int>> pts;
    pts.push_back({sy, sx}); // 0 = church
    for (auto &p : houses) pts.push_back(p);

    int V = N + 1;
    vector<vector<int>> adj(V);

    // For each row, connect consecutive special cells (church/house) in sorted x.
    {
        vector<vector<pair<int,int>>> row(H);
        for (int i = 0; i < V; i++) {
            auto [y, x] = pts[i];
            row[y].push_back({x, i});
        }
        for (int y = 0; y < H; y++) {
            auto &v = row[y];
            sort(v.begin(), v.end());
            for (int i = 0; i + 1 < (int)v.size(); i++) {
                int a = v[i].second, b = v[i + 1].second;
                adj[a].push_back(b);
                adj[b].push_back(a);
            }
        }
    }

    // For each column, connect consecutive special cells in sorted y.
    {
        vector<vector<pair<int,int>>> col(W);
        for (int i = 0; i < V; i++) {
            auto [y, x] = pts[i];
            col[x].push_back({y, i});
        }
        for (int x = 0; x < W; x++) {
            auto &v = col[x];
            sort(v.begin(), v.end());
            for (int i = 0; i + 1 < (int)v.size(); i++) {
                int a = v[i].second, b = v[i + 1].second;
                adj[a].push_back(b);
                adj[b].push_back(a);
            }
        }
    }

    // If too many houses, plain bit DP would be impossible, but this problem's
    // intended constraints allow Hamiltonian-path DP over houses.
    //
    // dp[mask][i]: number of ways to start at church (0), visit exactly houses in mask,
    // and end at house i (1..N, represented by bit i-1 in mask).
    //
    // Transition along graph edges, never visiting a house twice.
    //
    // Finally, sum states that can return from last house to church.

    if (N == 0) {
        // Start at church, no houses to visit, return to church:
        // staying put is not a flight route, so answer is 0.
        // (And they cannot land on church until all presents delivered; already true,
        // but no actual route exists.)
        cout << 0 << '\n';
        return 0;
    }

    int FULL = 1 << N;
    vector<vector<ll>> dp(FULL, vector<ll>(N + 1, 0));

    // Initial moves from church to adjacent houses
    for (int to : adj[0]) {
        if (to == 0) continue;
        dp[1 << (to - 1)][to] += 1;
    }

    for (int mask = 0; mask < FULL; mask++) {
        for (int last = 1; last <= N; last++) {
            ll cur = dp[mask][last];
            if (!cur) continue;

            for (int to : adj[last]) {
                if (to == 0) continue; // returning to church only at the end
                int b = to - 1;
                if (mask & (1 << b)) continue;
                dp[mask | (1 << b)][to] += cur;
            }
        }
    }

    ll ans = 0;
    int all = FULL - 1;
    for (int last = 1; last <= N; last++) {
        if (!dp[all][last]) continue;
        for (int to : adj[last]) {
            if (to == 0) {
                ans += dp[all][last];
                break;
            }
        }
    }

    cout << ans << '\n';
    return 0;
}

import sys

MOD = 100000


def main():
    input = sys.stdin.readline
    W, H = map(int, input().split())
    grid = [input().strip() for _ in range(H)]

    houses = []
    church = None
    for y in range(H):
        for x in range(W):
            c = grid[y][x]
            if c == 'H':
                houses.append((x, y))
            elif c == 'C':
                church = (x, y)

    n = len(houses)
    points = [church] + houses  # 0 = church, 1..n = houses

    # can_move[i][j]:
    # from point i to point j in one straight cardinal flight,
    # passing only over cells that are not empty lots.
    can_move = [[False] * (n + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        x1, y1 = points[i]
        for j in range(n + 1):
            if i == j:
                continue
            x2, y2 = points[j]
            if x1 != x2 and y1 != y2:
                continue

            ok = True
            if x1 == x2:
                step = 1 if y2 > y1 else -1
                y = y1 + step
                while y != y2:
                    if grid[y][x1] == '.':
                        ok = False
                        break
                    y += step
            else:
                step = 1 if x2 > x1 else -1
                x = x1 + step
                while x != x2:
                    if grid[y1][x] == '.':
                        ok = False
                        break
                    x += step

            # destination must be church or house, never empty by construction
            can_move[i][j] = ok

    # between_mask[i][j]:
    # bitmask of houses strictly between point i and point j on the straight path
    # (only meaningful if can_move[i][j] is True)
    between_mask = [[0] * (n + 1) for _ in range(n + 1)]

    house_index = {houses[k]: k for k in range(n)}  # 0-based among houses

    for i in range(n + 1):
        x1, y1 = points[i]
        for j in range(n + 1):
            if not can_move[i][j]:
                continue
            x2, y2 = points[j]
            mask = 0
            if x1 == x2:
                lo, hi = sorted((y1, y2))
                for y in range(lo + 1, hi):
                    if grid[y][x1] == 'H':
                        idx = house_index[(x1, y)]
                        mask |= 1 << idx
            else:
                lo, hi = sorted((x1, x2))
                for x in range(lo + 1, hi):
                    if grid[y1][x] == 'H':
                        idx = house_index[(x, y1)]
                        mask |= 1 << idx
            between_mask[i][j] = mask

    # DP[mask][i]:
    # number of ways to start at church, visit exactly houses in mask,
    # and currently be at point i (i=1..n, a visited house).
    size = 1 << n
    dp = [[0] * (n + 1) for _ in range(size)]

    # First move from church to a house
    for h in range(1, n + 1):
        bit = 1 << (h - 1)
        if can_move[0][h] and (between_mask[0][h] & bit) == 0 and between_mask[0][h] == 0:
            dp[bit][h] = 1

    for mask in range(size):
        for i in range(1, n + 1):
            cur = dp[mask][i]
            if cur == 0:
                continue
            # Move to an unvisited house j
            for j in range(1, n + 1):
                bit = 1 << (j - 1)
                if mask & bit:
                    continue
                if not can_move[i][j]:
                    continue
                # Cannot pass over already visited houses.
                if between_mask[i][j] & mask:
                    continue
                nmask = mask | bit
                dp[nmask][j] = (dp[nmask][j] + cur) % MOD

    full = (1 << n) - 1
    ans = 0

    # Return to church after all houses visited
    for i in range(1, n + 1):
        cur = dp[full][i]
        if cur == 0:
            continue
        if not can_move[i][0]:
            continue
        # Cannot pass over already visited houses on the way back
        if between_mask[i][0] & full:
            continue
        ans = (ans + cur) % MOD

    print(ans % MOD)


if __name__ == "__main__":
    main()
